    @Override public void onCreate(Bundle b){super.onCreate(b);db=new DbHelper(this);if(!getPreferences(MODE_PRIVATE).getBoolean("recentDefault21",false))getPreferences(MODE_PRIVATE).edit().putInt("sortMode",1).putBoolean("recentDefault21",true).apply();sortMode=getPreferences(MODE_PRIVATE).getInt("sortMode",1);if(sortMode<0||sortMode>=DbHelper.SORT_LABELS.length)sortMode=1;if(b!=null){String path=b.getString("pendingExport","");if(!path.isEmpty())pendingExport=new File(path);path=b.getString("camXlsx","");if(!path.isEmpty())camXlsx=new File(path);path=b.getString("pendingBackup","");if(!path.isEmpty())pendingBackup=new File(path);}buildUi();if(b!=null){search.setText(b.getString("query",""));groupFilter=b.getString("group","");favoritesOnly=b.getBoolean("favoritesOnly");groupButton.setText("그룹: "+(groupFilter.isEmpty()?"전체":groupFilter));favButton.setText(favoritesOnly?"★ 즐겨찾기":"☆ 즐겨찾기");Ui.styleButton(favButton,favoritesOnly);Ui.styleButton(groupButton,!groupFilter.isEmpty());}refresh();}
    @Override protected void onResume(){super.onResume();if(db!=null)refresh();}

