        LinearLayout filters=new LinearLayout(this);filters.setGravity(Gravity.CENTER_VERTICAL);favButton=Ui.button(this,"☆ 즐겨찾기");groupButton=Ui.button(this,"그룹: 전체");sortButton=Ui.button(this,sortLabel());for(Button b:new Button[]{favButton,groupButton,sortButton}){b.setTextSize(12*Ui.textScale(this));b.setPadding(Ui.dp(this,3),Ui.dp(this,1),Ui.dp(this,3),Ui.dp(this,1));b.setMinHeight(Ui.dp(this,40));b.setMinimumHeight(Ui.dp(this,40));b.setMaxLines(2);b.setEllipsize(TextUtils.TruncateAt.END);LinearLayout.LayoutParams lp=Ui.weight(1);lp.setMargins(Ui.dp(this,2),Ui.dp(this,2),Ui.dp(this,2),Ui.dp(this,3));filters.addView(b,lp);}root.addView(filters,Ui.mp(this));
