        favButton.setOnClickListener(v->{favoritesOnly=!favoritesOnly;favButton.setText(favoritesOnly?"★ 즐겨찾기":"☆ 즐겨찾기");Ui.styleButton(favButton,favoritesOnly);refresh();});groupButton.setOnClickListener(v->chooseGroup());sortButton.setOnClickListener(v->chooseSort());
        list=new ListView(this);list.setDividerHeight(1);list.setBackgroundColor(Color.WHITE);empty=Ui.text(this,"저장된 명함이 없습니다.\n‘명함 스캔’ 또는 ‘＋ 새 명함’을 사용하세요.\n기존 명함은 ‘관리 → 가져오기’로 옮길 수 있습니다.",16,false);empty.setGravity(Gravity.CENTER);
        FrameLayout content=new FrameLayout(this);content.addView(list,new FrameLayout.LayoutParams(-1,-1));content.addView(empty,new FrameLayout.LayoutParams(-1,-1));list.setEmptyView(empty);root.addView(content,new LinearLayout.LayoutParams(-1,0,1));
        list.setOnItemClickListener((p,v,pos,id)->{Contact c=(Contact)p.getItemAtPosition(pos);if(selectionMode!=null){toggleSelected(c.id);return;}startActivity(new Intent(this,DetailActivity.class).putExtra("id",c.id));});

        list.setOnItemLongClickListener((p,v,pos,id)->{beginSelection();toggleSelected(((Contact)p.getItemAtPosition(pos)).id);return true;});
        LinearLayout bottom=new LinearLayout(this);bottom.setGravity(Gravity.CENTER_VERTICAL);bottom.setPadding(0,Ui.dp(this,3),0,0);
